import{_ as i,o as s,c as t,a5 as e}from"./chunks/framework.CXroN2RO.js";const k=JSON.parse('{"title":"ネイティブビルドと IL2CPP","description":"","frontmatter":{"title":"ネイティブビルドと IL2CPP","study":{"source":"C++ Wiki","status":"published","summary":"UnityのIL2CPPによるILからC++への変換、AOT、コード生成、ネイティブ連携を調べる。","section":"reference","format":"article","domain":"languages"}},"headers":[],"relativePath":"languages/csharp/il2cpp.md","filePath":"languages/csharp/il2cpp.md"}'),n={name:"languages/csharp/il2cpp.md"};function l(r,a,p,h,o,d){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="ネイティブビルドと-il2cpp" tabindex="-1">ネイティブビルドと IL2CPP <a class="header-anchor" href="#ネイティブビルドと-il2cpp" aria-label="Permalink to &quot;ネイティブビルドと IL2CPP&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>IL2CPPは「<strong>C#(IL)をC++ソースに変換し、各プラットフォームのC++コンパイラでビルドする</strong>」Unityの仕組み。つまりあなたのC#コードは、最終的に<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">main.cpp から CPU命令までの旅</a>を通ってCPU命令になっています。C++を学ぶと、IL2CPPの制約・性能特性が「仕様の暗記」から「当然の帰結」に変わります。</p><h2 id="実行方式の全体地図" tabindex="-1">実行方式の全体地図 <a class="header-anchor" href="#実行方式の全体地図" aria-label="Permalink to &quot;実行方式の全体地図&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C#ソース ──Roslyn──&gt; IL(中間言語)+メタデータ</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─ [Mono/JIT]     実行時にILを機械語へ(エディタ再生、一部プラットフォーム)</span></span>
<span class="line"><span>    │                  柔軟(実行時コード生成OK)だが、起動後の変換コスト・JIT不可の環境あり</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─ [IL2CPP/AOT]   ビルド時にIL→UnityLinkerでストリッピング→C++→機械語(iOS・コンソールは事実上必須)</span></span>
<span class="line"><span>                       il2cpp.exe が .cpp を吐き、MSVC/Clang等が旅の②以降を実行</span></span></code></pre></div><ul><li>AOT (Ahead-Of-Time) = 事前コンパイル。JIT禁止のプラットフォーム(iOS等)で必須</li><li>生成C++の場所はUnityの版・対象・ビルド方法で異なる。旧版の<code>Library/Il2cppBuildCache</code>を固定パスとせず、2022系以降などのBeeによるビルドでは<code>Library/Bee/artifacts/.../il2cppOutput/cpp</code>などを、ビルドログや出力から探す。<a href="https://docs.unity.com/en-us/cloud/developer-data/upload-symbol-files-ci-troubleshooting" target="_blank" rel="noreferrer">Unityのビルド成果物の例</a></li></ul><h2 id="il2cppの制約をc-の知識で説明する" tabindex="-1">IL2CPPの制約をC++の知識で説明する <a class="header-anchor" href="#il2cppの制約をc-の知識で説明する" aria-label="Permalink to &quot;IL2CPPの制約をC++の知識で説明する&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unityでの経験則</th><th>ビルド・実行時の理由</th></tr></thead><tbody><tr><td>実行時のコード生成(Emit)不可</td><td>機械語は事前に全部作る。実行時にコンパイラはいない(<a href="/study/languages/csharp/templates-vs-generics.html">テンプレートとジェネリック</a>と同じ構図)</td></tr><tr><td>ジェネリックとAOTの制約は版・コード生成設定に依存</td><td>旧版では未生成の値型の組み合わせが失敗する例があった。Unity 2022.1以降はFull Generic Sharingのフォールバックにより、専用コードがない組み合わせも共有実装で扱える場合がある。ストリッピングや実行時コード生成の制約とは別に調べる</td></tr><tr><td>コードストリッピングでメソッドが消える(link.xml)</td><td>UnityLinkerがIL2CPP変換前にマネージドアセンブリから未使用と判定したILを取り除きます。リフレクションでの使用を静的に追えない場合は、<code>link.xml</code>などで必要な型やメソッドを保持します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/il2cpp-introduction.html" target="_blank" rel="noreferrer">UnityのIL2CPPビルド手順</a>・<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/unity-linker.html" target="_blank" rel="noreferrer">UnityLinkerの処理</a></td></tr><tr><td>iOSビルドが遅い</td><td>生成された膨大なC++のコンパイル(<a href="/study/tools/build/build-speed.html">ビルドが遅い理由</a>がフル適用)</td></tr><tr><td>IL2CPPの方が速いことが多い</td><td>C++コンパイラの最適化(<a href="/study/runtime/cpp-internals/optimization-and-ub.html">コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化</a>)がフルに掛かる。ただしGCはBoehmのまま(→ <a href="/study/runtime/memory/gc-and-csharp-comparison.html">GC比較</a>)</td></tr></tbody></table><h2 id="ネイティブプラグインとの境界-p-invoke" tabindex="-1">ネイティブプラグインとの境界(P/Invoke) <a class="header-anchor" href="#ネイティブプラグインとの境界-p-invoke" aria-label="Permalink to &quot;ネイティブプラグインとの境界(P/Invoke)&quot;">​</a></h2><p>Full Generic Sharingでは、特殊化された実装と共有実装で性能特性が異なる場合があります。「AOTでは未知のジェネリックの組み合わせはすべて実行できない」とはせず、使用するUnityの版・設定・保持されるメタデータを確認します。<a href="https://unity.com/blog/engine-platform/il2cpp-full-generic-sharing-in-unity-2022-1-beta" target="_blank" rel="noreferrer">Unity 2022.1の説明</a></p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// C#側</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DllImport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gamephysics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ネイティブDLL/静的ライブラリの関数を呼ぶ</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Simulate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// C++側 — extern &quot;C&quot; でC ABIに固定(→ シンボルと名前修飾)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> __declspec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dllexport) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Simulate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dt) {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* ... */</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><ul><li>境界のルールは<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">DLLのページ</a>そのまま: <strong>C ABI+プレーンなデータ</strong>(構造体はblittableに=参照型・stringを含めない)</li><li>呼び出しコストは1回あたり数十〜数百サイクル(マーシャリング)。<strong>細かく何度も呼ばず、まとめて渡す</strong>(配列でバッチ)が定石</li><li>文字列・配列を受け渡すときは、所有権を明確にします。GCはC#側のメモリを移動・回収するため、C++側でそのアドレスを保持してはいけません。ここでpinningを考えます。</li></ul><h2 id="burstとの関係" tabindex="-1">Burstとの関係 <a class="header-anchor" href="#burstとの関係" aria-label="Permalink to &quot;Burstとの関係&quot;">​</a></h2><p>Burst(HPC# → LLVMで機械語)は「C#の<strong>サブセット</strong>を、C++並みの最適化で直接コンパイルする」別ルート。IL2CPPが「C#全部をそこそこ速いC++に」なのに対し、Burstは「制限つきC#(<a href="/study/game/patterns/optimization-patterns.html">Data Locality</a>前提の書き方)を最速に」。<strong>制限の内容(参照型禁止・NativeContainer)は、本Wikiで学んだ「速いC++の条件」そのもの</strong>です。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>IL2CPPが変換するのはコードです。GCと管理ヒープの構造は変わらないため、Allocのスパイクは解消されません。</li><li>「エディタで動けば実機でも動く」— エディタはMono/JIT。AOT制約・ストリッピング・C++最適化の差でIL2CPP実機のみのバグは普通にある(→ <a href="/study/tools/build/build-configurations.html">Debug/Release差</a>と同じ構図)</li><li>IL2CPPが生成したC++の変数名は機械的ですが、コードの構造はこの辞典で扱うC++と同じです。実機でクラッシュしたときの解析で読むコードです。</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>JITとAOTの違いと、iOSでAOTが必須な理由は?</li><li>AOTのジェネリックコード生成とUnityLinkerのコードストリッピングは、それぞれビルドのどの段階で起きますか。リフレクション先の保持に<code>link.xml</code>を使うのはどちらですか。</li><li>P/Invoke境界の設計ルールを2つ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>自分のUnityプロジェクトをIL2CPPでビルドし、ビルドログから生成C++の場所を確認して、自作クラスに対応するファイルを探してください。Unityの版・対象・実際のパスと、「C#のクラスがC++でどう表現されているか」を3点メモします（メソッドテーブル、nullチェックの挿入など）。</p><hr><p>関連項目：<a href="/study/languages/csharp/headers-vs-asmdef.html">ヘッダー分割とAssembly Definition</a> / <a href="/study/languages/csharp/">学習ガイド</a> / <a href="/study/languages/csharp/memory-management-vs-gc.html">手動メモリ管理とGC</a></p>`,23)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
